{
    "from": "now-1h",
    "to": "now",
    "queries": [
        {
            "refId": "A",
            "datasource": {
                "uid": "{{dsUid}}"
            },
            "rawSql": "SELECT recvTimeTs / 1000 AS time, CAST(attrValue AS DECIMAL(6,1)) AS value FROM `urn_ngsi-ld_ClimateStation_ESP32001_ClimateStation` WHERE attrName = 'temperature' ORDER BY recvTimeTs DESC LIMIT 50",
            "format": "table"
        }
    ]
}

{
    "from": "now-1h",
    "to": "now",
    "queries": [
        {
            "refId": "A",
            "datasource": {
                "uid": "{{dsUid}}"
            },
            "rawSql": "SELECT attrValue AS estado, COUNT(*) AS amostras FROM `urn_ngsi-ld_ClimateStation_ESP32001_ClimateStation` WHERE attrName = 'state' AND recvTimeTs / 1000 > UNIX_TIMESTAMP() - 900 GROUP BY attrValue",
            "format": "table"
        }
    ]
}

{
    "from": "now-1h",
    "to": "now",
    "queries": [
        {
            "refId": "A",
            "datasource": {
                "uid": "{{dsUid}}"
            },
            "rawSql": "SELECT $__unixEpochGroupAlias(recvTimeTs / 1000, '1m'), AVG(CAST(attrValue AS DECIMAL(6,1))) AS media FROM `urn_ngsi-ld_ClimateStation_ESP32001_ClimateStation` WHERE attrName = 'temperature' AND $__unixEpochFilter(recvTimeTs / 1000) GROUP BY 1 ORDER BY 1",
            "format": "table"
        }
    ]
}
